// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(address caller, uint256 value, bytes calldata data) public {
        vm.assume(caller != c.Owner());
        vm.assume(value <= address(c).balance);
        vm.deal(caller, value);
        vm.deal(address(c), 1 ether);

        vm.prank(caller);
        try c.Command{value: value}(address(0), data) {
            assertTrue(false);
        } catch {
            assertTrue(true);
        }
    }
}
